import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-10-04","description":"","frontmatter":{"title":"AI 动态 · 2026-10-04","date":"2026-10-04T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-04.md","filePath":"news/2026-10/ai-news-2026-10-04.md","lastUpdated":null}'),s={name:"news/2026-10/ai-news-2026-10-04.md"};function i(o,e,l,d,c,p){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-10-04" tabindex="-1">AI 动态 · 2026-10-04 <a class="header-anchor" href="#ai-动态-·-2026-10-04" aria-label="Permalink to &quot;AI 动态 · 2026-10-04&quot;">​</a></h1><blockquote><p>截至 2026-10-04。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="openai安全员工离职-称公司-文化已崩坏" tabindex="-1">OpenAI安全员工离职，称公司“文化已崩坏” <a class="header-anchor" href="#openai安全员工离职-称公司-文化已崩坏" aria-label="Permalink to &quot;OpenAI安全员工离职，称公司“文化已崩坏”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-04">2026-10-04</time></p><p>OpenAI安全方向员工David Robinson宣布离职，并公开批评公司“文化已崩坏”，自嘲是“典型剧本”里的那种人：在头部AI公司任职、离职时发出严厉警告。这类离职声明近年反复出现，反映安全团队与商业化节奏之间的张力。对读者：若你依赖OpenAI做关键业务，建议把供应商治理与安全承诺纳入评估，并保留多模型备份方案。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/03/openai-safety-employee-resigns-claiming-the-companys-culture-is-broken/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="ai推高内存价格-7年前的nvidia-shield-tv涨价100美元" tabindex="-1">AI推高内存价格，7年前的Nvidia Shield TV涨价100美元 <a class="header-anchor" href="#ai推高内存价格-7年前的nvidia-shield-tv涨价100美元" aria-label="Permalink to &quot;AI推高内存价格，7年前的Nvidia Shield TV涨价100美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wired AI</span><time datetime="2026-10-04">2026-10-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/71c4be1c7f49.jpg" alt="配图"></p><p>Wired指出，受AI需求带动，凡带内存的硬件价格都在飙升，连上市7年的Nvidia Shield TV也涨了100美元。这说明AI对存储与内存的挤占已传导到消费电子终端，老设备同样难逃成本重估。对读者：做硬件选型或采购时，应把内存/存储涨价纳入BOM与预算预期，避免按旧价签长期合同。</p><p class="news-entry-source"><a href="https://www.wired.com/story/7-year-old-tv-now-100-dollars-more-expensive-thank-ai/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="卡普空-为-与ai共同制作游戏-的未来做准备" tabindex="-1">卡普空：为“与AI共同制作游戏”的未来做准备 <a class="header-anchor" href="#卡普空-为-与ai共同制作游戏-的未来做准备" aria-label="Permalink to &quot;卡普空：为“与AI共同制作游戏”的未来做准备&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-10-04">2026-10-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/db65f54893a9.jpg" alt="配图"></p><p>在Capcom Open Conference RE 2026上，程序员Satoshi Ishida介绍REX项目与RE Engine的下一代演进，指出《生化危机》量级的项目让简单任务也极其耗时，解决方案是把AI技术整合进开发工作流。有趣的是，其新作Pragmata主题恰是AI的恐怖，现实策略却相当拥抱AI。对读者：游戏与内容团队可关注AI在资产、流程自动化上的落地路径，但需同步建立版权与质量把关机制。</p><p class="news-entry-source"><a href="https://www.theverge.com/games/1004418/capcom-ai-game-development" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="aleph-alpha发布kolibri-78-1b英德moe-仅激活3-46b参数" tabindex="-1">Aleph Alpha发布Kolibri：78.1B英德MoE，仅激活3.46B参数 <a class="header-anchor" href="#aleph-alpha发布kolibri-78-1b英德moe-仅激活3-46b参数" aria-label="Permalink to &quot;Aleph Alpha发布Kolibri：78.1B英德MoE，仅激活3.46B参数&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-04">2026-10-04</time></p><p>Aleph Alpha开源Kolibri，一个78.1B参数的英德双语混合专家模型，每token仅激活3.46B参数，支持100万token上下文与按请求调节的推理强度。其Apache 2.0许可的FP8权重可跑在单张B200或H200上。稀疏MoE加长上下文，正在把“大模型单卡可跑”变成现实选项。对读者：若做多语言或长文档场景，可把Kolibri列入本地部署候选，重点验证英德之外的语言表现。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/04/aleph-alpha-releases-kolibri-a-78-1b-open-weight-english-german-moe-model-with-only-3-46b-active-parameters/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="谷歌把联邦学习搬进tee-gboard实现可外部验证的差分隐私" tabindex="-1">谷歌把联邦学习搬进TEE：Gboard实现可外部验证的差分隐私 <a class="header-anchor" href="#谷歌把联邦学习搬进tee-gboard实现可外部验证的差分隐私" aria-label="Permalink to &quot;谷歌把联邦学习搬进TEE：Gboard实现可外部验证的差分隐私&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-04">2026-10-04</time></p><p>Google Research公布新联邦学习系统，把梯度计算从手机移到经过认证的服务端TEE中。访问策略发布到Sigstore的Rekor日志，二进制可复现构建，因此中心化差分隐私可被外部核查。Gboard已用其训练英语和日语的下一个词预测。这为“既要集中训练又要隐私可验证”提供了工程范式。对读者：涉及用户数据的模型训练，可参考TEE+可复现构建+公开日志的组合来设计审计链路。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/04/google-research-moves-federated-learning-into-tees-gboard-now-trains-with-externally-verifiable-differential-privacy/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepseek-harness-v0-2发布官方桌面应用" tabindex="-1">DeepSeek Harness v0.2发布官方桌面应用 <a class="header-anchor" href="#deepseek-harness-v0-2发布官方桌面应用" aria-label="Permalink to &quot;DeepSeek Harness v0.2发布官方桌面应用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-04">2026-10-04</time></p><p>DeepSeek为其MIT许可的Agent框架Harness发布v0.2，新增macOS与Windows官方桌面应用。预览版加入插件管理器、文件与代码变更审查、定时自动化任务，并可通过OpenAI兼容端点接入非DeepSeek模型。开源Agent框架正从命令行走向桌面产品化。对读者：想搭内部Agent平台，可先评估Harness的插件与审查机制，注意其模型兼容层的稳定性。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/03/deepseek-harness-v0-2-brings-official-desktop-apps-to-its-open-source-agent-harness/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="微软-agent说它做完了-数据库不同意" tabindex="-1">微软：Agent说它做完了，数据库不同意 <a class="header-anchor" href="#微软-agent说它做完了-数据库不同意" aria-label="Permalink to &quot;微软：Agent说它做完了，数据库不同意&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-10-04">2026-10-04</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/05a4dbbb31f8.png" alt="配图"></p><p>Hugging Face上微软发布的文章讨论Agent任务完成度与真实系统状态不一致的问题：Agent声称已完成，但数据库校验失败。这类“自报成功”是Agent落地生产环境的高频故障，根源在于缺少可验证的副作用确认与事务边界。对读者：设计Agent写操作时，务必以数据库或外部系统的最终状态为准，加入幂等与回滚，别信Agent的完成声明。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/microsoft/thinkingbox" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="claude-code的-乐高-模式-mods机制让程序员玩上头" tabindex="-1">Claude Code的“乐高”模式：Mods机制让程序员玩上头 <a class="header-anchor" href="#claude-code的-乐高-模式-mods机制让程序员玩上头" aria-label="Permalink to &quot;Claude Code的“乐高”模式：Mods机制让程序员玩上头&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">极客公园</span><time datetime="2026-10-04">2026-10-04</time></p><p>Claude Code负责人Boris Cherny放出的Mods机制已于10月1日正式写入更新日志并默认开启。开发者用它做出像素宠物、断网小恐龙、呼吸引导动画，甚至塞进26万参数小模型实时写故事。一个改代码的工具被搭成了可扩展的“我的世界”。对读者：若团队重度使用Claude Code，可评估Mods做内部工作流定制，但需管控第三方Mod的权限与代码来源。</p><p class="news-entry-source"><a href="http://www.geekpark.net/news/372074" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="diff算法-虚拟dom-reconciliation-的技术难点" tabindex="-1">diff算法（虚拟DOM Reconciliation）的技术难点 <a class="header-anchor" href="#diff算法-虚拟dom-reconciliation-的技术难点" aria-label="Permalink to &quot;diff算法（虚拟DOM Reconciliation）的技术难点&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-10-04">2026-10-04</time></p><p>文章从理论最优解切入，解释虚拟DOM diff为何难：给定新旧两棵节点树，要找出把旧树变成新树的最少增删移操作序列，而“最少”本身在一般树上代价极高。这解释了主流框架为何采用启发式假设（同层比较、key标识）来把复杂度降到可接受范围。对读者：排查列表渲染错位或性能问题时，先检查key是否稳定唯一，再考虑是否需要手动优化更新粒度。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7692296625806229544" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const g=a(s,[["render",i]]);export{m as __pageData,g as default};
